#!/usr/bin/env bash
install_kube_vip(){ local manifest="$PROJECT_ROOT/templates/kube-vip/kube-vip.yaml" rendered; rendered=$(sed -e "s/__VIP__/$API_VIP/g" -e "s/__VERSION__/$KUBE_VIP_VERSION/g" "$manifest"); write_root_file /var/lib/rancher/k3s/server/manifests/kube-vip.yaml 600 "$rendered" || true; }
validate_kube_vip(){ local ds desired ready available; ds=$(kubectl_local -n kube-system get ds kube-vip -o jsonpath='{.status.desiredNumberScheduled}/{.status.numberReady}/{.status.numberAvailable}' 2>/dev/null) || { warn "kube-vip DaemonSet not found"; return 1; }; IFS=/ read -r desired ready available <<<"$ds"; if [[ $desired == "$ready" && $ready == "$available" ]]; then ok "kube-vip $ds"; else warn "kube-vip desired/ready/available: $ds"; return 1; fi; }
check_kube_vip_interface(){ local configured; configured=$(kubectl_local -n kube-system get ds kube-vip -o jsonpath='{.spec.template.spec.containers[0].env[?(@.name=="vip_interface")].value}' 2>/dev/null || true); if [[ -n $configured && $configured != "$PRIMARY_IFACE" ]]; then warn "Existing kube-vip pins interface '$configured', but this node uses '$PRIMARY_IFACE'. Reconcile the DaemonSet before declaring this node healthy."; return 1; fi; }
